const items = $input.all();
const rawData = items.map(i => i.json).filter(c => c && (c.id != null || c.session_id));
const count = rawData.length;

let casesSummary = '';
if (count > 0) {
  const topCases = rawData.slice(0, 3);
  casesSummary = topCases.map(c => {
    const session = c.session_id || ('ID-' + c.id);
    const wait = c.pending_minutes != null ? (c.pending_minutes + ' min') : '>1 min';
    const lastMsg = c.last_message ? (c.last_message.length > 70 ? c.last_message.substring(0, 67) + '...' : c.last_message) : 'Sin mensajes previos';
    return '• <b>Sesión:</b> <code>' + session + '</code> (espera: <b>' + wait + '</b>)\n  <i>« ' + lastMsg + ' »</i>';
  }).join('\n');
}

return [{
  json: {
    count: count,
    cases_summary: casesSummary,
    threshold_minutes: 1
  }
}];
